import { Component, ComponentInterface, h, Prop } from '@stencil/core';
import { Classification } from '../../types';

@Component({
  tag: 'groupui-classification-label',
  styleUrl: 'classification-label.scss',
  shadow: true,
})
export class ClassificationLabel implements ComponentInterface {
  /**
   * The classification type
   */
  @Prop({ reflect: true, mutable: true }) classification: Classification = 'public';

  /**
   * Toggles inverted colors
   */
  @Prop({ reflect: true, mutable: true }) inverted: boolean;

  private classificationLabel(): string {
    return this.classification.slice(0, 1).toUpperCase() + this.classification.slice(1);
  }

  render() {
    return <span>{this.classificationLabel()}</span>;
  }
}
